ALTER TABLE `pages` ADD `description` text DEFAULT '' NOT NULL;--> statement-breakpoint
-- The desktop sync keeps the description from the side that changed it last, like the other fields of a page.
DROP TRIGGER sync_pages_insert;--> statement-breakpoint
CREATE TRIGGER sync_pages_insert AFTER INSERT ON pages BEGIN
  UPDATE pages SET sync_clock = CAST(unixepoch('subsec') * 1000 AS INTEGER), field_clock = json_patch(json_object('parentId', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'kind', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'title', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'icon', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'fullWidth', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'cover', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'coverPosition', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'position', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'deletedAt', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'deletedBy', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'template', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'defaultTemplateId', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'locked', CAST(unixepoch('subsec') * 1000 AS INTEGER), 'description', CAST(unixepoch('subsec') * 1000 AS INTEGER)), (SELECT json_group_object('p:' || key, CAST(unixepoch('subsec') * 1000 AS INTEGER)) FROM json_each(coalesce(NEW.props, '{}')))) WHERE id = NEW.id AND NOT EXISTS (SELECT 1 FROM sync_state WHERE key = 'applying' AND value IS NOT NULL);
  INSERT INTO sync_changes (entity, entity_id, workspace_id, deleted, origin, at) VALUES ('page', NEW.id, NEW.workspace_id, 0, (SELECT value FROM sync_state WHERE key = 'applying'), CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;
