DROP TRIGGER sync_pages_update;--> statement-breakpoint
CREATE TRIGGER sync_pages_update AFTER UPDATE OF parent_id, kind, title, icon, full_width, cover, cover_position, position, deleted_at, deleted_by, template, default_template_id, locked, description, content_state, props ON pages BEGIN
  UPDATE pages SET sync_clock = CAST(unixepoch('subsec') * 1000 AS INTEGER), field_clock = json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(json_patch(coalesce(OLD.field_clock, '{}'), CASE WHEN OLD.parent_id IS NEW.parent_id THEN '{}' ELSE json_object('parentId', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.kind IS NEW.kind THEN '{}' ELSE json_object('kind', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.title IS NEW.title THEN '{}' ELSE json_object('title', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.icon IS NEW.icon THEN '{}' ELSE json_object('icon', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.full_width IS NEW.full_width THEN '{}' ELSE json_object('fullWidth', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.cover IS NEW.cover THEN '{}' ELSE json_object('cover', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.cover_position IS NEW.cover_position THEN '{}' ELSE json_object('coverPosition', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.position IS NEW.position THEN '{}' ELSE json_object('position', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.deleted_at IS NEW.deleted_at THEN '{}' ELSE json_object('deletedAt', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.deleted_by IS NEW.deleted_by THEN '{}' ELSE json_object('deletedBy', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.template IS NEW.template THEN '{}' ELSE json_object('template', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.default_template_id IS NEW.default_template_id THEN '{}' ELSE json_object('defaultTemplateId', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.locked IS NEW.locked THEN '{}' ELSE json_object('locked', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.description IS NEW.description THEN '{}' ELSE json_object('description', CAST(unixepoch('subsec') * 1000 AS INTEGER)) END), CASE WHEN OLD.props IS NEW.props THEN '{}' ELSE (SELECT json_group_object('p:' || k, CAST(unixepoch('subsec') * 1000 AS INTEGER)) FROM (
      SELECT n.key AS k FROM json_each(coalesce(NEW.props, '{}')) n
      WHERE NOT EXISTS (SELECT 1 FROM json_each(coalesce(OLD.props, '{}')) o WHERE o.key = n.key AND o.type = n.type AND o.value IS n.value)
      UNION
      SELECT o.key FROM json_each(coalesce(OLD.props, '{}')) o
      WHERE NOT EXISTS (SELECT 1 FROM json_each(coalesce(NEW.props, '{}')) n WHERE n.key = o.key))) END) WHERE id = NEW.id AND NOT EXISTS (SELECT 1 FROM sync_state WHERE key = 'applying' AND value IS NOT NULL);
  INSERT INTO sync_changes (entity, entity_id, workspace_id, deleted, origin, at) VALUES ('page', NEW.id, NEW.workspace_id, 0, (SELECT value FROM sync_state WHERE key = 'applying'), CAST(unixepoch('subsec') * 1000 AS INTEGER));
END;
